          "minItems": 1,
          "items": {
            "type": "object",
            "required": ["chapter_number", "chapter_title", "core_event"],
            "properties": {
              "chapter_number": {
                "type": "integer",
                "minimum": 1,
                "description": "章节编号"
              },
              "chapter_title": {
                "type": "string",
                "description": "章节标题"
              },
              "core_event": {
                "type": "string",
                "description": "本章核心事件（1-2句话）"
              },
              "emotional_tone": {
                "type": "string",
                "description": "本章情感基调"
              },
              "key_scenes": {
                "type": "array",
                "description": "本章关键场景列表",
                "items": {
                  "type": "string"
                }
              }
            }
          }
        },
        "turning_point": {
          "type": "string",
          "description": "本幕结尾的转折点"
        }
      }
    },
    "act_three": {
      "type": "object",
      "description": "第三幕：高潮+结局（20-30%篇幅）- X-Y化学反应爆发",
      "required": ["description", "key_chapters"],
      "properties": {
        "description": {
          "type": "string",
