              },
              "emotional_tone": {
                "type": "string",
                "description": "本章情感基调"
              },
              "key_scenes": {
                "type": "array",
                "description": "本章关键场景列表",
                "items": {
                  "type": "string"
                }
              }
            }
          }
        },
